---
import Layout from '../../layouts/Layout.astro';
import { getEntry, render } from 'astro:content';
const entry = await getEntry('books', Astro.params.slug!);
if (!entry) return Astro.rewrite('/404');
const { Content } = await render(entry);
const { title, author, year, rating, tags } = entry.data;
---
<Layout title={`${title} | Bookshelf`}>
  <h1>{title}</h1>
  <p>by {author}</p>
  <p>Published in {year}</p>
  <p>Rating: {rating}/5</p>
  <ul>{tags.map((t) => <li><a href="/books">{t}</a></li>)}</ul>
  <div><Content /></div>
  <button type="button" id="fav" data-slug={entry.id}>Add to favorites</button>
</Layout>
<script>
  const btn = document.getElementById('fav') as HTMLButtonElement;
  const slug = btn.dataset.slug!;
  const read = (): string[] => { try { return JSON.parse(localStorage.getItem('favorites') || '[]'); } catch { return []; } };
  const show = () => { btn.textContent = read().includes(slug) ? 'Remove from favorites' : 'Add to favorites'; };
  btn.addEventListener('click', () => {
    const f = read();
    localStorage.setItem('favorites', JSON.stringify(f.includes(slug) ? f.filter((s) => s !== slug) : [...f, slug]));
    show();
  });
  show();
</script>
