---
import Layout from '../layouts/Layout.astro';
import { validate, type Errors } from '../lib/contact';
let values = { name: '', email: '', message: '' };
let errors: Errors = {};
let success = '';
if (Astro.request.method === 'POST') {
  const d = await Astro.request.formData();
  const g = (k: string) => String(d.get(k) ?? '');
  values = { name: g('name'), email: g('email'), message: g('message') };
  errors = validate(values);
  if (!Object.keys(errors).length) success = `Thanks, ${values.name.trim()}! Your message has been sent.`;
}
---
<Layout title="Contact | Bookshelf">
  <h1>Contact</h1>
  {success && <p id="success">{success}</p>}
  {!success && (
  <form method="post" action="/contact" novalidate id="contact">
    <div>
      <label for="name">Name</label>
      <input type="text" id="name" name="name" value={values.name} />
      <span class="error" data-for="name">{errors.name}</span>
    </div>
    <div>
      <label for="email">Email</label>
      <input type="email" id="email" name="email" value={values.email} />
      <span class="error" data-for="email">{errors.email}</span>
    </div>
    <div>
      <label for="message">Message</label>
      <textarea id="message" name="message">{values.message}</textarea>
      <span class="error" data-for="message">{errors.message}</span>
    </div>
    <button type="submit">Send</button>
  </form>
  )}
</Layout>
<script>
  import { validate } from '../lib/contact';
  const form = document.getElementById('contact') as HTMLFormElement | null;
  form?.addEventListener('submit', (ev) => {
    const v = (n: string) => (form.elements.namedItem(n) as HTMLInputElement).value;
    const errors = validate({ name: v('name'), email: v('email'), message: v('message') }) as Record<string, string>;
    form.querySelectorAll<HTMLElement>('.error').forEach((el) => { el.textContent = errors[el.dataset.for!] ?? ''; });
    if (Object.keys(errors).length) ev.preventDefault();
  });
</script>
